// GinServerOptions provides options for the Gin server.
type GinServerOptions struct {
	BaseURL      string
	Middlewares  []MiddlewareFunc
	ErrorHandler func(*gin.Context, error, int)
}

// RegisterHandlers creates http.Handler with routing matching OpenAPI spec.
func RegisterHandlers(router gin.IRouter, si ServerInterface) {
	RegisterHandlersWithOptions(router, si, GinServerOptions{})
}

// RegisterHandlersWithOptions creates http.Handler with additional options
func RegisterHandlersWithOptions(router gin.IRouter, si ServerInterface, options GinServerOptions) {
	errorHandler := options.ErrorHandler
	if errorHandler == nil {
		errorHandler = func(c *gin.Context, err error, statusCode int) {
			c.JSON(statusCode, gin.H{"msg": err.Error()})
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandler:       errorHandler,
	}

	router.GET(options.BaseURL+"/healthz", wrapper.Healthz)
	router.GET(options.BaseURL+"/readyz", wrapper.Readyz)
	router.GET(options.BaseURL+"/auth/google", wrapper.StartGoogleAuth)
	router.GET(options.BaseURL+"/auth/google/callback", wrapper.GoogleCallback)
	router.POST(options.BaseURL+"/auth/logout", wrapper.Logout)
	router.GET(options.BaseURL+"/account", wrapper.GetAccount)
	router.PATCH(options.BaseURL+"/account", wrapper.UpdateAccount)
	router.POST(options.BaseURL+"/account/deactivate", wrapper.DeactivateAccount)
	router.GET(options.BaseURL+"/listings", wrapper.ListMineListings)
	router.POST(options.BaseURL+"/listings", wrapper.CreateListingDraft)
	router.GET(options.BaseURL+"/listings/:id", wrapper.GetMyListing)
	router.PATCH(options.BaseURL+"/listings/:id", wrapper.UpdateListing)
	router.POST(options.BaseURL+"/listings/:id/publish", wrapper.PublishListing)
	router.POST(options.BaseURL+"/listings/:id/pause", wrapper.PauseListing)
	router.GET(options.BaseURL+"/listings/:id/blocks", wrapper.ListBlocks)
	router.POST(options.BaseURL+"/listings/:id/blocks", wrapper.AddBlock)
	router.DELETE(options.BaseURL+"/listings/:id/blocks/:blockId", wrapper.RemoveBlock)
	router.GET(options.BaseURL+"/owner/onboarding", wrapper.GetOwnerOnboarding)
	router.PATCH(options.BaseURL+"/owner/onboarding", wrapper.UpdateOwnerOnboarding)
	router.GET(options.BaseURL+"/catalog/listings", wrapper.SearchCatalog)
	router.GET(options.BaseURL+"/catalog/listings/:id", wrapper.GetPublicListing)
	router.GET(options.BaseURL+"/catalog/listings/:id/calendar", wrapper.GetPublicCalendar)
	router.GET(options.BaseURL+"/catalog/categories", wrapper.ListCategories)
	router.GET(options.BaseURL+"/rentals", wrapper.ListMyRentals)
	router.POST(options.BaseURL+"/rentals", wrapper.CreateRental)
	router.GET(options.BaseURL+"/rentals/:id", wrapper.GetRental)
	router.POST(options.BaseURL+"/rentals/:id/authorize", wrapper.AuthorizeRentalPayment)
	router.POST(options.BaseURL+"/rentals/:id/accept", wrapper.AcceptRental)
	router.POST(options.BaseURL+"/rentals/:id/decline", wrapper.DeclineRental)
	router.POST(options.BaseURL+"/rentals/:id/cancel", wrapper.CancelRental)
	router.GET(options.BaseURL+"/rentals/:id/receipt", wrapper.GetRentalReceipt)
	router.GET(options.BaseURL+"/rentals/:id/cancellations", wrapper.GetRentalCancellation)
	router.POST(options.BaseURL+"/rentals/:id/cancellations", wrapper.CreateRentalCancellation)
	router.POST(options.BaseURL+"/payments/webhook", wrapper.PaymentWebhook)
	router.POST(options.BaseURL+"/rentals/:id/pickup", wrapper.RegisterRentalPickup)
	router.POST(options.BaseURL+"/rentals/:id/return", wrapper.RegisterRentalReturn)
	router.POST(options.BaseURL+"/rentals/:id/damage", wrapper.OpenDamageClaim)
	router.POST(options.BaseURL+"/damage/:id/respond", wrapper.RespondDamageClaim)
	router.POST(options.BaseURL+"/damage/:id/resolve", wrapper.StaffResolveDamage)
	router.POST(options.BaseURL+"/debt/:id/settle", wrapper.SettleDebt)
	router.POST(options.BaseURL+"/debt/:id/forgive", wrapper.ForgiveDebt)
}

